-- ============================================================
-- Schema: BRASIL | Engine: MySQL 8
-- PII columns marked with -- [PII]
-- ============================================================

CREATE DATABASE IF NOT EXISTS demo_brasil;
USE demo_brasil;

DROP TABLE IF EXISTS `clientes`;
CREATE TABLE `clientes` (
    `id` INT,
    `nome` VARCHAR(100),
    `sobrenome` VARCHAR(100),
    `email` VARCHAR(150),
    `telefone` VARCHAR(30),
    `cpf` VARCHAR(20),
    `data_nascimento` DATE,
    `genero` VARCHAR(10),
    `estado_civil` VARCHAR(20),
    `endereco_linha1` VARCHAR(200),
    `endereco_linha2` VARCHAR(100),
    `cidade` VARCHAR(100),
    `estado` VARCHAR(5),
    `cep` VARCHAR(10),
    `pais` VARCHAR(50)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

DROP TABLE IF EXISTS `funcionarios`;
CREATE TABLE `funcionarios` (
    `id` INT,
    `nome` VARCHAR(100),
    `sobrenome` VARCHAR(100),
    `email_corporativo` VARCHAR(150),
    `email_pessoal` VARCHAR(150),
    `telefone` VARCHAR(30),
    `cpf` VARCHAR(20),
    `data_nascimento` DATE,
    `cargo` VARCHAR(100),
    `departamento` VARCHAR(100),
    `salario` DECIMAL(12,2),
    `data_admissao` DATE,
    `endereco_linha1` VARCHAR(200),
    `endereco_linha2` VARCHAR(100),
    `cidade` VARCHAR(100),
    `estado` VARCHAR(5),
    `cep` VARCHAR(10),
    `banco` VARCHAR(100),
    `conta_bancaria` VARCHAR(30)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

DROP TABLE IF EXISTS `contas_bancarias`;
CREATE TABLE `contas_bancarias` (
    `id` INT,
    `numero_conta` VARCHAR(30),
    `agencia` VARCHAR(10),
    `tipo_conta` VARCHAR(30),
    `saldo` DECIMAL(14,2),
    `limite` DECIMAL(14,2),
    `titular` VARCHAR(200),
    `cpf_titular` VARCHAR(20),
    `banco` VARCHAR(100),
    `data_abertura` DATE,
    `status` VARCHAR(20)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

DROP TABLE IF EXISTS `cartoes_credito`;
CREATE TABLE `cartoes_credito` (
    `id` INT,
    `numero_cartao` VARCHAR(25),
    `nome_titular` VARCHAR(200),
    `validade` VARCHAR(8),
    `bandeira` VARCHAR(30),
    `limite` DECIMAL(12,2),
    `fatura_atual` DECIMAL(12,2),
    `status` VARCHAR(20),
    `cpf_titular` VARCHAR(20)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

DROP TABLE IF EXISTS `pedidos`;
CREATE TABLE `pedidos` (
    `id` INT,
    `numero_pedido` VARCHAR(20),
    `data_pedido` DATE,
    `cliente_nome` VARCHAR(200),
    `cliente_cpf` VARCHAR(20),
    `valor_total` DECIMAL(12,2),
    `status` VARCHAR(30),
    `endereco_entrega` VARCHAR(200),
    `complemento_entrega` VARCHAR(100),
    `cidade_entrega` VARCHAR(100),
    `cep_entrega` VARCHAR(10)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

DROP TABLE IF EXISTS `prontuarios_medicos`;
CREATE TABLE `prontuarios_medicos` (
    `id` INT,
    `paciente_nome` VARCHAR(200),
    `paciente_cpf` VARCHAR(20),
    `data_nascimento` DATE,
    `tipo_sanguineo` VARCHAR(5),
    `diagnostico` VARCHAR(200),
    `medicamentos` VARCHAR(200),
    `medico_responsavel` VARCHAR(200),
    `plano_saude` VARCHAR(100),
    `data_consulta` DATE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

DROP TABLE IF EXISTS `fornecedores`;
CREATE TABLE `fornecedores` (
    `id` INT,
    `nome_empresa` VARCHAR(200),
    `cnpj` VARCHAR(20),
    `nome_contato` VARCHAR(200),
    `email` VARCHAR(150),
    `telefone` VARCHAR(30),
    `endereco` VARCHAR(200),
    `cidade` VARCHAR(100),
    `estado` VARCHAR(5),
    `cep` VARCHAR(10),
    `segmento` VARCHAR(100)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

DROP TABLE IF EXISTS `transacoes`;
CREATE TABLE `transacoes` (
    `id` INT,
    `data_transacao` DATETIME,
    `tipo` VARCHAR(50),
    `valor` DECIMAL(14,2),
    `conta_origem` VARCHAR(30),
    `conta_destino` VARCHAR(30),
    `descricao` VARCHAR(200),
    `status` VARCHAR(30),
    `ip_origem` VARCHAR(50),
    `localizacao` VARCHAR(100)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

DROP TABLE IF EXISTS `logs_acesso`;
CREATE TABLE `logs_acesso` (
    `id` INT,
    `data_hora` DATETIME,
    `usuario_id` INT,
    `email_usuario` VARCHAR(150),
    `ip_address` VARCHAR(50),
    `user_agent` VARCHAR(300),
    `acao` VARCHAR(50),
    `recurso` VARCHAR(200),
    `status_code` INT,
    `localizacao` VARCHAR(100)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

DROP TABLE IF EXISTS `apolices_seguro`;
CREATE TABLE `apolices_seguro` (
    `id` INT,
    `numero_apolice` VARCHAR(20),
    `titular_nome` VARCHAR(200),
    `titular_cpf` VARCHAR(20),
    `data_nascimento` DATE,
    `tipo_seguro` VARCHAR(50),
    `cobertura` DECIMAL(14,2),
    `premio_mensal` DECIMAL(10,2),
    `data_inicio` DATE,
    `data_fim` DATE,
    `beneficiario` VARCHAR(200)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

DROP TABLE IF EXISTS `contratos`;
CREATE TABLE `contratos` (
    `id` INT,
    `numero_contrato` VARCHAR(20),
    `empresa_nome` VARCHAR(200),
    `empresa_cnpj` VARCHAR(20),
    `contato_nome` VARCHAR(200),
    `contato_email` VARCHAR(150),
    `contato_telefone` VARCHAR(30),
    `valor_contrato` DECIMAL(16,2),
    `data_inicio` DATE,
    `data_fim` DATE,
    `status` VARCHAR(20)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

DROP TABLE IF EXISTS `leads_marketing`;
CREATE TABLE `leads_marketing` (
    `id` INT,
    `nome` VARCHAR(100),
    `sobrenome` VARCHAR(100),
    `email` VARCHAR(150),
    `telefone` VARCHAR(30),
    `empresa` VARCHAR(200),
    `cargo` VARCHAR(100),
    `fonte` VARCHAR(50),
    `data_cadastro` DATE,
    `status` VARCHAR(30),
    `interesse` VARCHAR(100)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

